-- Cancellation reasons (D-160, decided 2026-10-25): every move to CANCELLED
-- records a reason code in the order history; `OTHER` needs a note.
-- Additive: one nullable column on order_status_event and two CHECKs.
--
-- Sections:
--   1. Column (generated by prisma migrate diff)
--   2. CHECK constraints (handwritten)
-- Handwritten objects are listed in apps/api/src/db/handwritten.ts.

-- ═══ 1. Generated by prisma migrate diff (Prisma 7.10.1) ════════════════════
-- AlterTable
ALTER TABLE "order_status_event" ADD COLUMN     "reason" TEXT;


-- ═══ 2. CHECK constraints ════════════════════════════════════════════════════
-- The codes are CANCEL_REASONS in @sanea/shared (a test compares the lists).
ALTER TABLE "order_status_event" ADD CONSTRAINT "order_status_event_reason_check"
  CHECK ((("to_status" = 'CANCELLED') = ("reason" IS NOT NULL))
     AND ("reason" IS NULL OR "reason" IN ('CUSTOMER_REQUESTED', 'CUSTOMER_UNREACHABLE',
       'SUSPECTED_FRAUD', 'OUT_OF_STOCK', 'ADDRESS_UNSERVICEABLE', 'OTHER',
       'PAYMENT_NOT_COMPLETED', 'NOT_CONFIRMED_IN_WINDOW', 'PAID_NO_STOCK')));
ALTER TABLE "order_status_event" ADD CONSTRAINT "order_status_event_other_note_check"
  CHECK ("reason" IS DISTINCT FROM 'OTHER' OR btrim(coalesce("note", '')) <> '');
